select MONTH(start_date) as MONTH,CAR_ID,count(*) as RECORDS from car_rental_company_rental_history where start_date >= "2022-08-01" and start_date < "2022-11-01" and car_id in (select car_id from car_rental_company_rental_history where start_date between "2022-08-01" and "2022-10-31" group by car_id having count(*) >= 5)
group by MONTH(start_date), CAR_ID order by MONTH, CAR_ID desc;